WITH enriched AS (SELECT *, CORR(cost, price) OVER w_ordered AS corr_cost_price, NTILE(4) OVER (PARTITION BY brand ORDER BY stock_qty DESC, id ASC) AS stock_qty_bucket, DENSE_RANK() OVER (ORDER BY stock_qty ASC) AS stock_qty_dense_rank FROM products WINDOW w_ordered AS (PARTITION BY category)) SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags FROM enriched ORDER BY brand ASC NULLS FIRST, id ASC;
